// convertReq wraps a fixture payload + query into a ConvertRequest. Fixtures
// mirror the real tmdb v3 payloads (language=ru-RU serves russian
// title/overview/genre names; poster_path is a relative path). No I/O.
func convertReq(t *testing.T, payload string, query map[string]any) *metadatav1.ConvertRequest {
	t.Helper()
	req := &metadatav1.ConvertRequest{RawResponse: []byte(payload)}
	if query != nil {
		q, err := structpb.NewStruct(query)
		if err != nil {
			t.Fatalf("fixture query struct: %v", err)
		}
		req.Query = q
	}
	return req
}

// TestConvertNamespaceFields pins the RU-first namespace shape (box 1.4): a
// detail payload converts into title{russian, romaji: original_title},
// description, genres, score, kind, status, episodes, aired_on, poster
// (poster_path composed to an absolute image.tmdb.org URL) and url — the
// movie shape and, separately, the tv shape (name/original_name/first_air_
// date/number_of_episodes); resolved_ids names tmdb_id; the provenance hints
// carry plugin_version + source_url on every field.
func TestConvertNamespaceFields(t *testing.T) {
	p := &sourceImpl{}

	t.Run("movie detail fills the RU-first namespace", func(t *testing.T) {
		payload := `{
			"id": 550, "title": "Бойцовский клуб", "original_title": "Fight Club",
			"overview": "Человек, страдающий от бессонницы…",
			"genres": [{"id": 18, "name": "Драма"}, {"id": 53, "name": "Триллер"}],
			"vote_average": 8.4, "status": "Released",
			"release_date": "1999-10-15", "poster_path": "/pB8BM7pdSp6B6Ie7kZOZ.jpg"
		}`
		res, err := p.Convert(context.Background(), convertReq(t, payload, map[string]any{"tmdb_id": int64(550)}))
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if res.GetError() != nil {
			t.Fatalf("unexpected Convert error: %v", res.GetError())
		}
		meta := res.GetMetadata().AsMap()
		title, _ := meta["title"].(map[string]any)
		if title["russian"] != "Бойцовский клуб" || title["romaji"] != "Fight Club" {
			t.Errorf("title = %v, want {russian, romaji: original_title}", title)
		}
		for k, want := range map[string]any{
			"description": "Человек, страдающий от бессонницы…",
			"score":       8.4,
			"kind":        "movie",
			"status":      "Released",
			"aired_on":    "1999-10-15",
			"poster":      "https://image.tmdb.org/t/p/original/pB8BM7pdSp6B6Ie7kZOZ.jpg",
			"url":         "https://www.themoviedb.org/movie/550",
		} {
			if meta[k] != want {
				t.Errorf("meta[%q] = %v, want %v", k, meta[k], want)
			}
		}
		if _, has := meta["episodes"]; has {
			t.Errorf("meta[episodes] = %v, want ABSENT (movies carry no episode count)", meta["episodes"])
		}
		genres, _ := meta["genres"].([]any)
		if len(genres) != 2 || genres[0] != "Драма" || genres[1] != "Триллер" {
			t.Errorf("genres = %v, want the served names in payload order", genres)
		}
		ids, _ := meta[resolvedIDsKey].(map[string]any)
		if ids[idKey] != float64(550) {
			t.Errorf("resolved_ids = %v, want {tmdb_id: 550}", ids)
		}
		for field, hint := range res.GetProvenance() {
			if hint.GetPluginId() != pluginID || hint.GetPluginVersion() != pluginVersion {
				t.Errorf("provenance[%q] = %s@%s, want %s@%s", field,
					hint.GetPluginId(), hint.GetPluginVersion(), pluginID, pluginVersion)
			}
			if hint.GetSourceUrl() != "https://www.themoviedb.org/movie/550" {
				t.Errorf("provenance[%q].source_url = %q, want the page URL", field, hint.GetSourceUrl())
			}
		}
	})

	t.Run("tv detail fills the tv-shaped namespace", func(t *testing.T) {
		payload := `{
			"id": 1396, "name": "Во все тяжкие", "original_name": "Breaking Bad",
			"overview": "Школьный учитель химии…",
			"genres": [{"id": 18, "name": "Драма"}],
			"vote_average": 8.9, "status": "Ended",
			"number_of_episodes": 62, "first_air_date": "2008-01-20",
			"poster_path": "/ggFHVNu6YYI5L9pCfOacjizRGt.jpg"
		}`
		res, err := p.Convert(context.Background(), convertReq(t, payload, map[string]any{"tmdb_id": int64(1396)}))
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if res.GetError() != nil {
			t.Fatalf("unexpected Convert error: %v", res.GetError())
		}
		meta := res.GetMetadata().AsMap()
		title, _ := meta["title"].(map[string]any)
		if title["russian"] != "Во все тяжкие" || title["romaji"] != "Breaking Bad" {
			t.Errorf("title = %v, want {russian: name, romaji: original_name}", title)
		}
		if meta["kind"] != "tv" {
			t.Errorf("meta[kind] = %v, want tv", meta["kind"])
		}
		if meta["episodes"] != float64(62) {
			t.Errorf("meta[episodes] = %v, want 62 (number_of_episodes)", meta["episodes"])
		}
		if meta["aired_on"] != "2008-01-20" {
			t.Errorf("meta[aired_on] = %v, want first_air_date", meta["aired_on"])
		}
		if meta["poster"] != "https://image.tmdb.org/t/p/original/ggFHVNu6YYI5L9pCfOacjizRGt.jpg" {
			t.Errorf("meta[poster] = %v, want the absolute image.tmdb.org URL", meta["poster"])
		}
		if meta["url"] != "https://www.themoviedb.org/tv/1396" {
			t.Errorf("meta[url] = %v, want the tv page URL", meta["url"])
		}
	})
}

// TestConvertCandidatePrefersYearKindAgreement pins the candidate selection
// (box 1.4): over the search envelope {"results":[…]} the selected candidate
// is the one agreeing with the parsed year and the movie/tv kind; a payload
// with no agreeing candidate still yields a deterministic, non-erroring
// selection (ties break by upstream order); absent signals degrade the score
// instead of erroring.
func TestConvertCandidatePrefersYearKindAgreement(t *testing.T) {
	p := &sourceImpl{}

	t.Run("year and kind agreement pick the candidate", func(t *testing.T) {
		payload := `{"page": 1, "results": [
			{"id": 10, "title": "Wrong One", "original_title": "Wrong One",
			 "release_date": "1996-04-01", "vote_average": 9.0},
			{"id": 20, "title": "Идеальная грусть", "original_title": "Perfect Blue",
			 "release_date": "1997-08-05", "vote_average": 8.0},
			{"id": 30, "title": "Right Year Only", "original_title": "Half Agree",
			 "release_date": "1997-02-14", "vote_average": 7.0}
		]}`
		query := map[string]any{"title": "Perfect Blue", "kind": "movie", "year": int64(1997)}
		res, err := p.Convert(context.Background(), convertReq(t, payload, query))
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if res.GetError() != nil {
			t.Fatalf("unexpected Convert error: %v", res.GetError())
		}
		ids, _ := res.GetMetadata().AsMap()[resolvedIDsKey].(map[string]any)
		if got := ids[idKey]; got != float64(20) {
			t.Fatalf("selected candidate id = %v, want 20 (year + kind agree)", got)
		}
	})

	t.Run("kind alone breaks a year tie toward the agreeing kind", func(t *testing.T) {
		payload := `{"page": 1, "results": [
			{"id": 40, "title": "Wrong Series", "name": "Wrong Series",
			 "first_air_date": "1997-03-01"},
			{"id": 50, "title": "Right Movie", "original_title": "Right Movie",
			 "release_date": "1997-03-01"}
		]}`
		query := map[string]any{"title": "Right Movie", "kind": "movie", "year": int64(1997)}
		res, err := p.Convert(context.Background(), convertReq(t, payload, query))
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		ids, _ := res.GetMetadata().AsMap()[resolvedIDsKey].(map[string]any)
		if got := ids[idKey]; got != float64(50) {
			t.Fatalf("selected candidate id = %v, want 50 (both agree on year, kind disambiguates)", got)
		}
	})

	t.Run("nothing agreeing still selects deterministically without error", func(t *testing.T) {
		payload := `{"page": 1, "results": [
			{"id": 10, "title": "Первый", "original_title": "First", "release_date": "2001-01-01"},
			{"id": 20, "title": "Второй", "original_title": "Second", "release_date": "2002-01-01"}
		]}`
		res, err := p.Convert(context.Background(), convertReq(t, payload, map[string]any{"title": "Первый"}))
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if res.GetError() != nil {
			t.Fatalf("nothing-agrees selection errored: %v", res.GetError())
		}
		ids, _ := res.GetMetadata().AsMap()[resolvedIDsKey].(map[string]any)
		if got := ids[idKey]; got != float64(10) {
			t.Fatalf("selected candidate id = %v, want 10 (upstream order breaks ties)", got)
		}
	})
}

// TestConvertHonestAbsence pins the honest-absence law (box 1.4): a field the
// upstream does not serve is ABSENT from the namespace — never an empty
// string, zero, empty array, or placeholder.
func TestConvertHonestAbsence(t *testing.T) {
	p := &sourceImpl{}

	t.Run("missing overview genres poster date status score stay absent", func(t *testing.T) {
		payload := `{
			"id": 42, "title": "Минималист", "original_title": "Minimal"
		}`
		res, err := p.Convert(context.Background(), convertReq(t, payload, nil))
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if res.GetError() != nil {
			t.Fatalf("unexpected Convert error: %v", res.GetError())
		}
		meta := res.GetMetadata().AsMap()
		for _, k := range []string{"description", "genres", "poster", "aired_on", "status", "score", "episodes"} {
			if v, has := meta[k]; has {
				t.Errorf("meta[%q] = %v, want the key ABSENT (honest absence)", k, v)
			}
		}
		title, _ := meta["title"].(map[string]any)
		if title["russian"] != "Минималист" || title["romaji"] != "Minimal" {
			t.Errorf("title = %v, want the served fields kept while the rest stay absent", title)
		}
	})

	t.Run("an empty genres array composes no genres key", func(t *testing.T) {
		payload := `{"id": 43, "title": "Без Жанров", "original_title": "No Genres", "genres": []}`
		res, err := p.Convert(context.Background(), convertReq(t, payload, nil))
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if v, has := res.GetMetadata().AsMap()["genres"]; has {
			t.Errorf("meta[genres] = %v, want the key ABSENT (never an empty array)", v)
		}
	})

	t.Run("a title served in one language only keeps the other slot absent", func(t *testing.T) {
		payload := `{"id": 44, "original_title": "Original Only"}`
		res, err := p.Convert(context.Background(), convertReq(t, payload, nil))
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		title, _ := res.GetMetadata().AsMap()["title"].(map[string]any)
		if title["romaji"] != "Original Only" {
			t.Errorf("title = %v, want romaji kept", title)
		}
		if v, has := title["russian"]; has {
			t.Errorf("title.russian = %v, want ABSENT (upstream served no localized title)", v)
		}
	})
}

