// TestConvertCreditsToCast pins the credits→cast conversion (box 1.5): the
// anchored film plan's credits extra converts into the media-data convention
// cast array — one entry per cast member, name the actor, role the
// character, photo_url the profile_path composed absolute — with unusable
// entries skipped and per-entry fields honestly absent when the payload
// serves none; the cast field rides the provenance hints like every
// namespace field.
func TestConvertCreditsToCast(t *testing.T) {
	p := &sourceImpl{}

	t.Run("credits members convert into the convention entries", func(t *testing.T) {
		payload := `{
			"id": 550, "title": "Бойцовский клуб", "original_title": "Fight Club"
		}`
		credits := `{"id": 550, "cast": [
			{"name": "Брэд Питт", "character": "Тайлер Дёрден",
			 "profile_path": "/nUPbjuMblleFhFq0nvWY58BNkAF.jpg"},
			{"name": "Эдвард Нортон", "character": "Рассказчик"},
			{"name": "Мит Лоуф", "character": "Роберт Полсон", "profile_path": ""},
			{"character": "Безымянный без актёра"}
		], "crew": [{"name": "Дэвид Финчер", "job": "Director"}]}`
		req := convertReq(t, payload, map[string]any{"tmdb_id": int64(550)})
		req.ExtraResponses = creditsExtra(t, credits, true)
		res, err := p.Convert(context.Background(), req)
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if res.GetError() != nil {
			t.Fatalf("unexpected Convert error: %v", res.GetError())
		}
		cast, ok := res.GetMetadata().AsMap()[castKey].([]any)
		if !ok || len(cast) != 3 {
			t.Fatalf("cast = %v (ok=%v), want 3 usable entries (the nameless one skipped)", cast, ok)
		}
		first, _ := cast[0].(map[string]any)
		if first["name"] != "Брэд Питт" || first["role"] != "Тайлер Дёрден" ||
			first["photo_url"] != "https://image.tmdb.org/t/p/original/nUPbjuMblleFhFq0nvWY58BNkAF.jpg" {
			t.Errorf("cast[0] = %v, want {name: actor, role: character, photo_url: absolute profile URL}", first)
		}
		second, _ := cast[1].(map[string]any)
		if second["name"] != "Эдвард Нортон" || second["role"] != "Рассказчик" {
			t.Errorf("cast[1] = %v, want name + role kept", second)
		}
		if _, has := second["photo_url"]; has {
			t.Errorf("cast[1].photo_url = %v, want ABSENT (the payload served no profile_path)", second["photo_url"])
		}
		third, _ := cast[2].(map[string]any)
		if third["name"] != "Мит Лоуф" {
			t.Errorf("cast[2] = %v, want the empty profile_path kept as an absent field, entry kept", third)
		}
		if _, has := third["photo_url"]; has {
			t.Errorf("cast[2].photo_url = %v, want ABSENT (an empty path composes no URL)", third["photo_url"])
		}
		if _, has := res.GetProvenance()[castKey]; !has {
			t.Errorf("provenance carries no %q hint, want one like every namespace field", castKey)
		}
	})
}

// TestConvertCastAbsentWithoutCredits pins the honest-absence law for cast
// (box 1.5): a credits payload with no usable entries, one that never
// arrived, or a search (unanchored) run — whose plan declares no extras —
// leaves the cast field ABSENT, never an empty array.
func TestConvertCastAbsentWithoutCredits(t *testing.T) {
	p := &sourceImpl{}

	t.Run("an anchored payload with no credits body leaves cast absent", func(t *testing.T) {
		payload := `{"id": 550, "title": "Бойцовский клуб", "original_title": "Fight Club"}`
		res, err := p.Convert(context.Background(), convertReq(t, payload, map[string]any{"tmdb_id": int64(550)}))
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if v, has := res.GetMetadata().AsMap()[castKey]; has {
			t.Errorf("meta[cast] = %v, want the key ABSENT (no extras arrived)", v)
		}
	})

	t.Run("a soft-failed credits extra leaves cast absent", func(t *testing.T) {
		payload := `{"id": 550, "title": "Бойцовский клуб", "original_title": "Fight Club"}`
		req := convertReq(t, payload, map[string]any{"tmdb_id": int64(550)})
		req.ExtraResponses = creditsExtra(t, `{"cast": []}`, false)
		res, err := p.Convert(context.Background(), req)
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if v, has := res.GetMetadata().AsMap()[castKey]; has {
			t.Errorf("meta[cast] = %v, want the key ABSENT (the extra never fetched)", v)
		}
	})

	t.Run("a credits payload with no usable entries composes no cast key", func(t *testing.T) {
		payload := `{"id": 550, "title": "Бойцовский клуб", "original_title": "Fight Club"}`
		req := convertReq(t, payload, map[string]any{"tmdb_id": int64(550)})
		req.ExtraResponses = creditsExtra(t, `{"id": 550, "cast": [{"character": "никто"}]}`, true)
		res, err := p.Convert(context.Background(), req)
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if v, has := res.GetMetadata().AsMap()[castKey]; has {
			t.Errorf("meta[cast] = %v, want the key ABSENT (never an empty array)", v)
		}
	})

	t.Run("a search run stays single-fetch without cast", func(t *testing.T) {
		payload := `{"page": 1, "results": [{"id": 550, "title": "Бойцовский клуб",
			"original_title": "Fight Club", "release_date": "1999-10-15"}]}`
		query := map[string]any{"title": "Fight Club", "kind": "movie", "year": int64(1999)}
		res, err := p.Convert(context.Background(), convertReq(t, payload, query))
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if res.GetError() != nil {
			t.Fatalf("unexpected Convert error: %v", res.GetError())
		}
		meta := res.GetMetadata().AsMap()
		if v, has := meta[castKey]; has {
			t.Errorf("meta[cast] = %v, want the key ABSENT (search plans declare no extras)", v)
		}
		if v, has := meta[resolvedIDsKey]; !has {
			t.Errorf("resolved_ids absent — the search run should still carry it, got %v", v)
		}
	})
}

