// TestConvertSeasonToEpisodeTitles pins the season→episode-titles conversion
// (box 1.6): the anchored series plan's season extra converts into
// ConvertResult.EpisodeTitle entries keyed by the source's episode_number,
// each entry's metadata carrying BOTH convention episode fields — title (the
// episode name) and description (the episode overview, honestly absent when
// the payload serves none) — while the run namespace wraps as usual and the
// same-position season body composes no cast (the shape-keyed plan
// discrimination).
func TestConvertSeasonToEpisodeTitles(t *testing.T) {
	p := &sourceImpl{}

	t.Run("season episodes convert into keyed title+description entries", func(t *testing.T) {
		payload := `{
			"id": 1396, "name": "Во все тяжкие", "original_name": "Breaking Bad",
			"overview": "Школьный учитель химии…", "first_air_date": "2008-01-20"
		}`
		season := `{"_id": "5ac1b2", "season_number": 1, "name": "Во все тяжкие: Сезон 1", "episodes": [
			{"episode_number": 1, "name": "Пилот", "overview": "Диагноз — неоперабельный рак…"},
			{"episode_number": 2, "name": "Кошка в мешке…"}
		]}`
		req := convertReq(t, payload, map[string]any{"tmdb_id": int64(1396), "season": int64(1)})
		req.ExtraResponses = seasonExtra(t, season, true)
		res, err := p.Convert(context.Background(), req)
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if res.GetError() != nil {
			t.Fatalf("unexpected Convert error: %v", res.GetError())
		}
		entries := res.GetEpisodeTitles()
		if len(entries) != 2 {
			t.Fatalf("episode_titles = %d entries, want 2 (payload order preserved)", len(entries))
		}
		first := entries[0]
		if first.GetEpisode() != 1 {
			t.Errorf("entries[0].episode = %d, want 1 (keyed by episode_number)", first.GetEpisode())
		}
		meta := first.GetMetadata().AsMap()
		if meta["title"] != "Пилот" {
			t.Errorf("entries[0].metadata[title] = %v, want the episode name", meta["title"])
		}
		if meta["description"] != "Диагноз — неоперабельный рак…" {
			t.Errorf("entries[0].metadata[description] = %v, want the episode overview", meta["description"])
		}
		second := entries[1]
		if second.GetEpisode() != 2 {
			t.Errorf("entries[1].episode = %d, want 2", second.GetEpisode())
		}
		smeta := second.GetMetadata().AsMap()
		if smeta["title"] != "Кошка в мешке…" {
			t.Errorf("entries[1].metadata[title] = %v, want the episode name", smeta["title"])
		}
		if v, has := smeta["description"]; has {
			t.Errorf("entries[1].metadata[description] = %v, want ABSENT (the payload served no overview)", v)
		}
	})

	t.Run("the namespace still wraps while the entries ride outside it", func(t *testing.T) {
		payload := `{"id": 1396, "name": "Во все тяжкие", "original_name": "Breaking Bad"}`
		season := `{"episodes": [{"episode_number": 3, "name": "…И коробка в мешке", "overview": "..."}]}`
		req := convertReq(t, payload, map[string]any{"tmdb_id": int64(1396), "season": int64(1)})
		req.ExtraResponses = seasonExtra(t, season, true)
		res, err := p.Convert(context.Background(), req)
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		meta := res.GetMetadata().AsMap()
		if meta["kind"] != "tv" {
			t.Errorf("meta[kind] = %v, want the namespace converted as usual", meta["kind"])
		}
		if _, has := meta["episode_titles"]; has {
			t.Errorf("meta[episode_titles] present — entries must ride ConvertResult.EpisodeTitles, never the namespace")
		}
		if len(res.GetEpisodeTitles()) != 1 {
			t.Errorf("episode_titles = %v, want the single keyed entry", res.GetEpisodeTitles())
		}
	})

	t.Run("a series run's season body composes no cast", func(t *testing.T) {
		payload := `{"id": 1396, "name": "Во все тяжкие", "original_name": "Breaking Bad"}`
		season := `{"episodes": [{"episode_number": 1, "name": "Пилот", "overview": "..."}]}`
		req := convertReq(t, payload, map[string]any{"tmdb_id": int64(1396), "season": int64(1)})
		req.ExtraResponses = seasonExtra(t, season, true)
		res, err := p.Convert(context.Background(), req)
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if v, has := res.GetMetadata().AsMap()[castKey]; has {
			t.Errorf("meta[cast] = %v, want ABSENT (a season body is not a credits payload)", v)
		}
	})
}

// TestConvertEpisodeTitlesHonestAbsence pins the honest-absence law for the
// episode-titles contributions (box 1.6): an unfetched extra, an unparsable
// payload, a payload with no usable entries, a nameless entry, or a credits
// body (the film plan's same-position extra, which is not a season payload)
// contributes nothing — never an empty or placeholder entry.
func TestConvertEpisodeTitlesHonestAbsence(t *testing.T) {
	p := &sourceImpl{}
	seriesQuery := map[string]any{"tmdb_id": int64(1396), "season": int64(1)}
	seriesPayload := `{"id": 1396, "name": "Во все тяжкие", "original_name": "Breaking Bad"}`

	t.Run("an unfetched season extra contributes nothing", func(t *testing.T) {
		req := convertReq(t, seriesPayload, seriesQuery)
		req.ExtraResponses = seasonExtra(t, `{"episodes": [{"episode_number": 1, "name": "Пилот"}]}`, false)
		res, err := p.Convert(context.Background(), req)
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if got := res.GetEpisodeTitles(); len(got) != 0 {
			t.Errorf("episode_titles = %v, want none (the extra never fetched)", got)
		}
	})

	t.Run("an unparsable season extra contributes nothing", func(t *testing.T) {
		req := convertReq(t, seriesPayload, seriesQuery)
		req.ExtraResponses = seasonExtra(t, `not json at all`, true)
		res, err := p.Convert(context.Background(), req)
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if res.GetError() != nil {
			t.Fatalf("the PRIMARY run must stay clean, got error %v", res.GetError())
		}
		if got := res.GetEpisodeTitles(); len(got) != 0 {
			t.Errorf("episode_titles = %v, want none (unparsable payload)", got)
		}
	})

	t.Run("a season with no usable entries composes no contributions", func(t *testing.T) {
		req := convertReq(t, seriesPayload, seriesQuery)
		req.ExtraResponses = seasonExtra(t, `{"season_number": 1, "episodes": []}`, true)
		res, err := p.Convert(context.Background(), req)
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if got := res.GetEpisodeTitles(); len(got) != 0 {
			t.Errorf("episode_titles = %v, want none (never an empty entry)", got)
		}
	})

	t.Run("a nameless episode is skipped while named ones convert", func(t *testing.T) {
		req := convertReq(t, seriesPayload, seriesQuery)
		req.ExtraResponses = seasonExtra(t, `{"episodes": [
			{"episode_number": 1, "overview": "no name served"},
			{"episode_number": 2, "name": "Кошка в мешке…"}
		]}`, true)
		res, err := p.Convert(context.Background(), req)
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		entries := res.GetEpisodeTitles()
		if len(entries) != 1 {
			t.Fatalf("episode_titles = %d entries, want 1 (the nameless one contributes nothing)", len(entries))
		}
		if entries[0].GetEpisode() != 2 {
			t.Errorf("entries[0].episode = %d, want 2", entries[0].GetEpisode())
		}
	})

	t.Run("the film plan's credits extra composes no episode titles", func(t *testing.T) {
		payload := `{"id": 550, "title": "Бойцовский клуб", "original_title": "Fight Club"}`
		credits := `{"id": 550, "cast": [{"name": "Брэд Питт", "character": "Тайлер Дёрден"}]}`
		req := convertReq(t, payload, map[string]any{"tmdb_id": int64(550)})
		req.ExtraResponses = creditsExtra(t, credits, true)
		res, err := p.Convert(context.Background(), req)
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if got := res.GetEpisodeTitles(); len(got) != 0 {
			t.Errorf("episode_titles = %v, want none (a credits body is not a season payload)", got)
		}
	})
}

// TestConvertSearchRunCarriesNoContributions pins the search-run law (box
// 1.6): an unanchored run declares no extras, so it carries neither episode
// titles nor cast — no contributions at all, only the candidate namespace.
func TestConvertSearchRunCarriesNoContributions(t *testing.T) {
	p := &sourceImpl{}
	payload := `{"page": 1, "results": [{"id": 1396, "name": "Во все тяжкие",
		"original_name": "Breaking Bad", "first_air_date": "2008-01-20"}]}`
	query := map[string]any{"title": "Breaking Bad", "season": int64(1)}
	res, err := p.Convert(context.Background(), convertReq(t, payload, query))
	if err != nil {
		t.Fatalf("Convert: %v", err)
	}
	if res.GetError() != nil {
		t.Fatalf("unexpected Convert error: %v", res.GetError())
	}
	if got := res.GetEpisodeTitles(); len(got) != 0 {
		t.Errorf("episode_titles = %v, want none (search runs declare no extras)", got)
	}
	if v, has := res.GetMetadata().AsMap()[castKey]; has {
		t.Errorf("meta[cast] = %v, want ABSENT (search runs declare no extras)", v)
	}
	ids, _ := res.GetMetadata().AsMap()[resolvedIDsKey].(map[string]any)
	if ids[idKey] != float64(1396) {
		t.Errorf("resolved_ids = %v, want the selected candidate carried as usual", ids)
	}
}

// TestMergeNamespaceOnlyStripsResolvedIds pins the namespace write (box 1.7):
// Merge writes ONLY document.sources["tmdb"] — the namespace-only law, the
// core validates the namespace and stamps _provenance/_view authoritatively —
// and strips the reserved resolved_ids entry (it is core-side identifier
// input, never a namespace field). The view bindings ride as the plugin's
// informational proposal, each naming the tmdb source.
func TestMergeNamespaceOnlyStripsResolvedIds(t *testing.T) {
	p := &sourceImpl{}
	incoming, err := structpb.NewStruct(map[string]any{
		"kind":         "movie",
		"title":        map[string]any{"russian": "Бойцовский клуб", "romaji": "Fight Club"},
		resolvedIDsKey: map[string]any{idKey: int64(550)},
	})
	if err != nil {
		t.Fatalf("fixture incoming struct: %v", err)
	}
	res, err := p.Merge(context.Background(), &metadatav1.MergeRequest{Incoming: incoming, PluginId: pluginID})
	if err != nil {
		t.Fatalf("Merge: %v", err)
	}
	data := res.GetDocument().GetData().AsMap()
	if len(data) != 1 {
		t.Fatalf("document top-level keys = %v, want exactly {sources} (namespace-only law)", data)
	}
	sources, _ := data["sources"].(map[string]any)
	ns, _ := sources[pluginID].(map[string]any)
	if _, has := ns[resolvedIDsKey]; has {
		t.Errorf("sources.%s carries reserved %s, want it stripped for doc.identifiers", pluginID, resolvedIDsKey)
	}
	if ns["kind"] != "movie" || ns["title"] == nil {
		t.Errorf("sources.%s = %v, want the incoming namespace fields kept", pluginID, ns)
	}
	for _, vb := range res.GetView() {
		if vb.GetSource() != pluginID {
			t.Errorf("view[%q].source = %q, want %q", vb.GetFieldPath(), vb.GetSource(), pluginID)
		}
	}
}
